                                     float xdistIn = decodeFloat(smp.ba) * 16383.0;
                                     float ydist = abs(y);
                                     float distOut = length(float2(xdistOut, ydist));
                                     float distIn = length(float2(xdistIn, ydist));
                                     nearestInside = min(nearestInside, distIn);
                                     nearestOutside = min(nearestOutside, distOut);
                             }
                             float4 texColor = baseColor;
                             float4 result;
                             float adjusted = (amzp_featherMode>0.5)
                                     ? clamp((nearestInside / radius2) - amzp_bias, 0.0, 1.0)
                                     : nearestInside / radius2;
                             float p = (amzp_gaussMode>0.5)
                                     ? exp(-pow(adjusted / (amzp_hardness * ((amzp_featherMode>0.5) ? amzp_feather : 1.0) + 0.001), 2.0))
                                     : smoothstep(radius2 + 0.51, amzp_hardness * radius2 - 0.51, nearestInside);
