                                     result = float4(amzp_color.rgb, 1.0) * texColor.a;
                             } else if (int(amzp_blendMode) == 1) {
                                     result = float4((texColor.rgb / texColor.a) * amzp_color.rgb, 1.0) * texColor.a;
                             } else if (int(amzp_blendMode) == 2) {
                                     result = float4(1.0 - ((1.0 - (texColor.rgb / texColor.a)) * (1.0 - amzp_color.rgb)), 1.0) * texColor.a;
