                              float p1 = 1. - smoothstepRev(adjEnd,adjEnd+adjFeather,pp);
                             amzOutput = (amzp_premulMode>0.5)
                                     ? float4(mix(texColor.rgb * amzp_compAlpha, result.rgb*p0*p1, p * amzp_alpha), texColor.a)
                                     : mix(texColor * amzp_compAlpha, result, amzp_alpha * p*p0*p1);
                     }
             }

