        float2 project(float2 a, float2 b) {
            return (dot(a,b)/dot(b,b)) * b;
        }
        float smoothstepRev(float edge0, float edge1, float x) {
            if(edge0 == edge1) return step(edge0, x);
            else return smoothstep(edge0, edge1, x);
        }
             float2 encodeFloat(float v) {
                      float2 enc = fract(float2(1.0, 255.0) * v);
                     enc.x -= enc.y / 255.0;
                     return enc;
             }
             float decodeFloat(float2 v) {
                     return dot(v, float2(1.0, 1.0 / 255.0));
             }
             void amzRender() {
                     float4 baseColor = amzTexture(0, amzScreenNorm().st);
                     if (amzp_radius < 0.5) {
                             amzOutput = baseColor;
                             return;
                     }
                     float2 texSize = getTexSize((screen.zw/1.0));
                     float scale = min(texSize.x, texSize.y);
                     float radius2 = amzp_radius * scale / 1024.0;
                     float q = (amzp_adaptMode>0.5)
                             ? max(radius2 / 32.0, 1.0)
                             : max(pow(radius2, 1.24) / radius2, radius2 / 40.0);
                     int from = -amzIntMax(1, int(radius2 / q));
                     int to = amzIntMax(1, int(radius2 / q));
                     float px = 1.0 / texSize.x;
                     float py = 1.0 / texSize.y;
                     float sdx = 0.0;
                     float sdy = 0.0;
                     if (amzPass == 0) {
                             float nearestOutside = 16383.0;
                             float nearestInside = 16383.0;
                             for (int i = from; i < to; i++) {
                                     float x = float(i) * q;
                                     float2 uv = float2(amzScreenNorm().s + (x - sdx) * (px / 1.0), amzScreenNorm().t);
                                     float4 smp = amzTexture(0, uv);
                                     float xdistOut = smp.a > 0.0 ? abs(x) : radius2 * 2.0;
                                     float xdistIn = smp.a < 0.003 ? abs(x) : radius2 * 2.0;
                                     nearestOutside = min(nearestOutside, xdistOut);
                                     nearestInside = min(nearestInside, xdistIn);
                             }
                             amzOutput = float4(
                                     encodeFloat(nearestOutside / 16383.0),
                                     encodeFloat(nearestInside / 16383.0)
                             );
                     }
                     if (amzPass == 1) {
                             float nearestOutside = 16383.0;
                             float nearestInside = 16383.0;
                             for (int i = from; i < to; i++) {
                                     float y = float(i) * q;
                                     float2 uv = float2(amzScreenNorm().s, amzScreenNorm().t + (y + sdy) * (py / 1.0));
                                     uv += float2((0.0+amzp_glowOffset.x), (0.0+amzp_glowOffset.y))*float2(-1.,1.)/500.;
                                     float4 smp = amzTexture(1, uv);
                                     float xdistOut = decodeFloat(smp.rg) * 16383.0;
                                     float xdistIn = decodeFloat(smp.ba) * 16383.0;
                                     float ydist = abs(y);
                                     float distOut = length(float2(xdistOut, ydist));
                                     float distIn = length(float2(xdistIn, ydist));
                                     nearestInside = min(nearestInside, distIn);
                                     nearestOutside = min(nearestOutside, distOut);
                             }
                             float4 texColor = baseColor;
                             float4 result;
                             float adjusted = (amzp_featherMode>0.5)
                                     ? clamp((nearestInside / radius2) - amzp_bias, 0.0, 1.0)
                                     : nearestInside / radius2;
                             float p = (amzp_gaussMode>0.5)
                                     ? exp(-pow(adjusted / (amzp_hardness * ((amzp_featherMode>0.5) ? amzp_feather : 1.0) + 0.001), 2.0))
                                     : smoothstep(radius2 + 0.51, amzp_hardness * radius2 - 0.51, nearestInside);
                             p = (amzp_gammaMode>0.5) ? pow(p, 1.0 / amzp_gammaSoft) : p;
                             if (int(amzp_blendMode) == 0) {
                                     result = float4(amzp_color.rgb, 1.0) * texColor.a;
                             } else if (int(amzp_blendMode) == 1) {
                                     result = float4((texColor.rgb / texColor.a) * amzp_color.rgb, 1.0) * texColor.a;
                             } else if (int(amzp_blendMode) == 2) {
                                     result = float4(1.0 - ((1.0 - (texColor.rgb / texColor.a)) * (1.0 - amzp_color.rgb)), 1.0) * texColor.a;
                             } else {
                                     result = float4(amzp_color.rgb, 1.0) * texColor.a;
                             }
                              float adjStart = amzp_start;
                              float adjEnd = amzp_end;
                              float adjFeather = amzp_featherr/100.0;
                              float rad = amzp_angle * 0.0174533;
                              float2 vv = normalize(float2(cos(rad),-sin(rad)));
                              float pp = dot(amzLayerNorm().st-float2(0.5,0.5), vv)+0.5;
                              float p0 = smoothstepRev(adjStart-adjFeather,adjStart,pp);
                              float p1 = 1. - smoothstepRev(adjEnd,adjEnd+adjFeather,pp);
                             amzOutput = (amzp_premulMode>0.5)
                                     ? float4(mix(texColor.rgb * amzp_compAlpha, result.rgb*p0*p1, p * amzp_alpha), texColor.a)
                                     : mix(texColor * amzp_compAlpha, result, amzp_alpha * p*p0*p1);
                     }
             }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
